AS x(id bigint,store_id bigint,sku text,new_code text,before jsonb);
DO $$ BEGIN
 IF (SELECT count(*) FROM stores WHERE organization_id=1 AND
    ((id=1 AND code='4483_R_SAINT_DENIS') OR (id=2 AND code='CHINATOWN') OR (id=3 AND code='ST_CATHERINE'))) <> 3
 THEN RAISE EXCEPTION 'TARGET_STORE_MISMATCH'; END IF;
 IF (SELECT max(version::int) FROM flyway_schema_history WHERE success) <> 37
    OR EXISTS(SELECT 1 FROM flyway_schema_history WHERE NOT success)
 THEN RAISE EXCEPTION 'SCHEMA_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM store_addons WHERE store_id IN (1,2,3))
 THEN RAISE EXCEPTION 'CATALOG_ALREADY_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM store_modules WHERE module_key='UBER_EATS' AND enabled)
    OR EXISTS(SELECT 1 FROM uber_eats_store_mappings WHERE enabled)
 THEN RAISE EXCEPTION 'PRODUCTION_UBER_MUST_REMAIN_OFF'; END IF;
 IF (SELECT count(*) FROM approved_options e JOIN menu_item_options o ON o.id=e.id
      JOIN menu_items i ON i.id=o.menu_item_id
      WHERE i.store_id=e.store_id AND i.sku=e.sku AND to_jsonb(o)=e.before) <> 195
 THEN RAISE EXCEPTION 'APPROVED_OPTION_CHANGED'; END IF;
 IF (SELECT count(*) FROM menu_item_options o JOIN menu_items i ON i.id=o.menu_item_id
      WHERE i.store_id IN (1,2,3) AND o.is_active AND
       (o.option_group='ADD_ON' OR (coalesce(o.option_group,'')='' AND o.option_type='addon'))) <> 195
 THEN RAISE EXCEPTION 'ACTIVE_ADDON_INVENTORY_CHANGED'; END IF;
END $$;
-- Protected complete rows, compared within this transaction snapshot (concurrent live activity excluded).
CREATE TEMP TABLE preservation_before(domain text PRIMARY KEY,fingerprint text) ON COMMIT DROP;
INSERT INTO preservation_before SELECT 'orders',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM orders t;
INSERT INTO preservation_before SELECT 'order_items',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM order_items t;
INSERT INTO preservation_before SELECT 'order_item_options',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM order_item_options t;
INSERT INTO preservation_before SELECT 'print_jobs',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM print_jobs t;
INSERT INTO preservation_before SELECT 'kitchen_tasks',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM kitchen_tasks t;
INSERT INTO preservation_before SELECT 'production_tasks',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM production_tasks t;
INSERT INTO preservation_before SELECT 'inventory_transactions',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM inventory_transactions t;
INSERT INTO preservation_before SELECT 'printer_configs',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM printer_configs t;
INSERT INTO preservation_before SELECT 'printer_assignments',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM printer_assignments t;
INSERT INTO preservation_before SELECT 'store_devices',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM store_devices t;
INSERT INTO preservation_before SELECT 'store_modules',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM store_modules t;
INSERT INTO preservation_before SELECT 'uber_eats_store_mappings',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM uber_eats_store_mappings t;
INSERT INTO preservation_before SELECT 'uber_eats_menu_mappings',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM uber_eats_menu_mappings t;
INSERT INTO preservation_before SELECT 'eligibility',md5(string_agg(id||':'||menu_item_id||':'||is_active::text,',' ORDER BY id)) FROM menu_item_options;
INSERT INTO organization_addon_definitions(organization_id,code,created_at,updated_at)
SELECT 1,code,now(),now() FROM approved_catalog ON CONFLICT(organization_id,code) DO NOTHING;
INSERT INTO store_addons(store_id,organization_id,organization_addon_definition_id,name_zh,name_en,price,active,created_at,updated_at)
SELECT s.id,s.organization_id,d.id,c.name_zh,c.name_en,c.price,true,now(),now()
FROM stores s CROSS JOIN approved_catalog c
JOIN organization_addon_definitions d ON d.organization_id=1 AND d.code=c.code
WHERE s.id IN (1,2,3);
UPDATE menu_item_options o SET store_addon_id=a.id,store_addon_store_id=a.store_id,addon_eligible=true,
 option_code=d.code,option_group='ADD_ON',option_type='addon',name_zh=a.name_zh,name_en=a.name_en,
 price_delta=a.price,updated_at=now()
FROM approved_options e JOIN store_addons a ON a.store_id=e.store_id
JOIN organization_addon_definitions d ON d.id=a.organization_addon_definition_id AND d.code=e.new_code
WHERE o.id=e.id;
UPDATE stores SET menu_revision=coalesce(menu_revision,1)+1,menu_updated_at=now(),updated_at=now() WHERE id IN (1,2,3);
INSERT INTO audit_logs(store_id,action,entity_type,entity_id,summary,metadata_json,created_at)
SELECT id,'OWNER_APPROVED_ADDON_RECONCILIATION','STORE',id,
 'Owner-confirmed canonical Add-ons and existing item references; history and eligibility preserved',
 jsonb_build_object('decision','OWNER_20261006','canonical_count',15,'linked_option_count',
 (SELECT count(*) FROM approved_options WHERE store_id=s.id),'history_changed',false)::text,now()
FROM stores s WHERE id IN (1,2,3);
CREATE TEMP TABLE preservation_after(LIKE preservation_before INCLUDING ALL) ON COMMIT DROP;
INSERT INTO preservation_after SELECT 'orders',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM orders t;
INSERT INTO preservation_after SELECT 'order_items',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM order_items t;
INSERT INTO preservation_after SELECT 'order_item_options',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM order_item_options t;
INSERT INTO preservation_after SELECT 'print_jobs',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM print_jobs t;
INSERT INTO preservation_after SELECT 'kitchen_tasks',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM kitchen_tasks t;
INSERT INTO preservation_after SELECT 'production_tasks',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM production_tasks t;
INSERT INTO preservation_after SELECT 'inventory_transactions',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM inventory_transactions t;
INSERT INTO preservation_after SELECT 'printer_configs',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM printer_configs t;
INSERT INTO preservation_after SELECT 'printer_assignments',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM printer_assignments t;
INSERT INTO preservation_after SELECT 'store_devices',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM store_devices t;
INSERT INTO preservation_after SELECT 'store_modules',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM store_modules t;
INSERT INTO preservation_after SELECT 'uber_eats_store_mappings',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM uber_eats_store_mappings t;
INSERT INTO preservation_after SELECT 'uber_eats_menu_mappings',md5(coalesce(string_agg(row_to_json(t)::text,'' ORDER BY t.id),'')) FROM uber_eats_menu_mappings t;
INSERT INTO preservation_after SELECT 'eligibility',md5(string_agg(id||':'||menu_item_id||':'||is_active::text,',' ORDER BY id)) FROM menu_item_options;
DO $$ BEGIN
 IF EXISTS(SELECT * FROM preservation_before EXCEPT SELECT * FROM preservation_after)
 THEN RAISE EXCEPTION 'PROTECTED_DATA_CHANGED'; END IF;
 IF (SELECT count(*) FROM store_addons WHERE store_id IN (1,2,3))<>45
 THEN RAISE EXCEPTION 'CATALOG_COUNT_MISMATCH'; END IF;
 IF (SELECT count(*) FROM approved_options e JOIN menu_item_options o ON o.id=e.id
     JOIN store_addons a ON a.id=o.store_addon_id AND a.store_id=e.store_id
     JOIN organization_addon_definitions d ON d.id=a.organization_addon_definition_id AND d.code=e.new_code
     WHERE o.addon_eligible AND o.is_active AND o.name_zh=a.name_zh AND o.name_en=a.name_en AND o.price_delta=a.price)<>195
 THEN RAISE EXCEPTION 'REFERENCE_READBACK_MISMATCH'; END IF;
END $$;
SELECT json_build_object('catalog_rows',45,'linked_options',195,'protected_data_unchanged',true,'eligibility_preserved',true);
COMMIT;
